// Validate migration parameters and pick the right source API config.
// Also: reset workflow static-data counters at the start of every run so a
// re-trigger does not re-add the previous run's totals.

const data = $getWorkflowStaticData('global');
data.migrationTotal = 0;
data.migrationSuccess = 0;
data.migrationErrors = 0;
data.migrationErrorList = [];

const input = $input.first().json ?? {};
const source = (input.source ?? 'mem0').toLowerCase();
const userId = input.userId ?? process.env.MIGRATION_DEFAULT_USER_ID ?? 'default-tenant';
const limit = Math.min(Math.max(Number(input.limit ?? 1000), 1), 10000);

if (!['mem0', 'zep'].includes(source)) {
  throw new Error(`Unsupported source: ${source}. Use 'mem0' or 'zep'.`);
}

const mem0ApiKey = input.mem0ApiKey ?? process.env.MEM0_API_KEY;
const zepApiKey = input.zepApiKey ?? process.env.ZEP_API_KEY;
const zepProjectId = input.zepProjectId ?? process.env.ZEP_PROJECT_ID;

if (source === 'mem0' && !mem0ApiKey) {
  throw new Error('Source is mem0 but MEM0_API_KEY is not set.');
}
if (source === 'zep' && !zepApiKey) {
  throw new Error('Source is zep but ZEP_API_KEY is not set.');
}

const config = source === 'mem0'
  ? {
      url: `https://api.mem0.ai/v1/memories/?user_id=${encodeURIComponent(userId)}&page_size=${limit}`,
      headers: {
        'Authorization': `Token ${mem0ApiKey}`,
        'Content-Type': 'application/json',
      },
    }
  : {
      url: `https://api.getzep.com/api/v2/users/${encodeURIComponent(userId)}/memory?lastn=${limit}`,
      headers: {
        'Authorization': `Api-Key ${zepApiKey}`,
        'Content-Type': 'application/json',
        'X-Zep-Project-Id': zepProjectId ?? '',
      },
    };

return [{
  json: {
    source,
    userId,
    limit,
    config,
    startedAt: new Date().toISOString(),
  },
}];

// Transform source API response into a uniform list of records.
// Mem0 returns { results: [{ id, memory, user_id, created_at, metadata }] }
// Zep returns { messages: [{ uuid, content, role_type, metadata, created_at }] }
//
// We map to a uniform shape:
//   { sourceId, sourceSystem, content, userId, createdAt, metadata, role? }

const fetched = $input.first().json;
const validate = $('Validate + Configure').item.json;
const source = validate.source;
const userId = validate.userId;

let records = [];

if (source === 'mem0') {
  const list = fetched?.results ?? fetched?.memories ?? (Array.isArray(fetched) ? fetched : []);
  records = list.map(m => ({
    sourceId: String(m.id ?? m.memory_id ?? ''),
    sourceSystem: 'mem0',
    content: String(m.memory ?? m.text ?? '').trim(),
    userId: m.user_id ?? userId,
    createdAt: m.created_at ?? m.timestamp ?? new Date().toISOString(),
    metadata: m.metadata ?? {},
    categories: m.categories ?? [],
  }));
} else if (source === 'zep') {
  const list = fetched?.messages ?? fetched?.facts ?? (Array.isArray(fetched) ? fetched : []);
  records = list.map(m => ({
    sourceId: String(m.uuid ?? m.id ?? m.fact_id ?? ''),
    sourceSystem: 'zep',
    content: String(m.content ?? m.fact ?? '').trim(),
    userId: m.session_id ?? userId,
    createdAt: m.created_at ?? new Date().toISOString(),
    metadata: m.metadata ?? {},
    role: m.role_type ?? m.role,
  }));
}

// Drop empty content
records = records.filter(r => r.sourceId && r.content);

return records.map(r => ({ json: r }));

// Build StudioMeyer Memory write payload per record.
// Each source record becomes:
//   - 1 entity (entityType: migrated-memory) keyed by source-id
//   - 1 observation on that entity with the original content
//   - 1 learning (category: import) with source-system tag
//
// Also: increments workflow static-data counters that Migration Report reads
// at the end. n8n's $('NodeName').all() in a done-branch does not aggregate
// across loop iterations, so we accumulate explicitly here.

const records = $input.all();
const out = [];

const data = $getWorkflowStaticData('global');
data.migrationTotal = (Number(data.migrationTotal) || 0) + records.length;

for (const r of records) {
  const rec = r.json;
  const entityName = `${rec.sourceSystem}-${rec.sourceId.slice(0, 32)}`;
  const tagsBase = ['migrated', `source-${rec.sourceSystem}`, `import-${new Date().toISOString().slice(0, 10)}`];
  if (rec.userId) tagsBase.push(`user-${String(rec.userId).slice(0, 32)}`);

  out.push({
    json: {
      entityName,
      entityType: 'migrated-memory',
      content: rec.content,
      tags: tagsBase,
      learnContent: `[Migrated from ${rec.sourceSystem}] ${rec.content.slice(0, 200)}`,
      observationContent: `[${rec.createdAt}] ${rec.content}`.slice(0, 2000),
      sourceMetadata: rec.metadata,
      sourceId: rec.sourceId,
    },
  });
}

return out;

// Migration Report: counts records that went into the loop.
// n8n's $('NodeName').all() in a done-branch does not aggregate across loop iterations,
// so we use workflow static-data set by Build Memory Payload to track total records.
// Per-record success/failure counting requires an inline counter Code node after each
// memory write, which would clutter the canvas. Users who want per-record audit should
// monitor n8n's execution log for this workflow's run-id, where each batch shows per-item
// success/failure on the standard pin or error pin.

const validate = $('Validate + Configure').item.json;
const data = $getWorkflowStaticData('global');
const totalRecords = Number(data.migrationTotal ?? 0);

const finishedAt = new Date().toISOString();
const startedAt = validate.startedAt;
const durationMs = new Date(finishedAt).getTime() - new Date(startedAt).getTime();

return [{
  json: {
    source: validate.source,
    userId: validate.userId,
    limit: validate.limit,
    totalRecords,
    startedAt,
    finishedAt,
    durationMs,
    durationSec: Math.round(durationMs / 1000),
    summary: `Migrated ${totalRecords} records from ${validate.source} for user ${validate.userId} in ${Math.round(durationMs / 1000)}s. Per-record success/failure available in n8n execution log for this workflow run.`,
    note: "Re-running the same migration is safe: Memory's gatekeeper deduplicates writes by content similarity, idempotency tags include source-id + import-date.",
  },
}];
